const float miter = 100.0;

float mt(float x, float y, float px, float py) {
    float x1 = px, y1 = py, x2 = 0.0, y2 = 0.0;

    float it = 0.0;
    while (it < miter) {
        if (x1 * x1 + y1 * y1 > 4.0) break;
        x2 = x1 * x1 - y1 * y1;
        y2 = 2.0 * x1 * y1;
        x2 += x;
        y2 += y;
        x1 = x2;
        y1 = y2;
        it++;
    }
    return it/miter;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/(iResolution.x);
    float ar = iResolution.y/iResolution.x;



    vec2 or = vec2(0.0,0.0);
    float sc = 0.25;


    vec3 col = mt(0.3*cos(iTime/3.0), 0.1*sin(iTime/3.0),(uv.x - 0.5)/sc + or.x,(uv.y-0.5*ar)/sc+or.y)*vec3(1,1,1);

    fragColor = vec4(col,1.0);
}
